package main

import (
	"bytes"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"
	"unicode"

	"gopkg.in/yaml.v3"
)

type durationValue time.Duration

func (d *durationValue) UnmarshalYAML(node *yaml.Node) error {
	var text string
	if err := node.Decode(&text); err != nil {
		return err
	}
	value, err := time.ParseDuration(text)
	if err != nil {
		return err
	}
	*d = durationValue(value)
	return nil
}

type clientConfig struct {
	GatewayURL    string        `yaml:"gateway_url"`
	TokenFile     string        `yaml:"token_file"`
	CAFile        string        `yaml:"ca_file"`
	LED           string        `yaml:"led"`
	ActivityHold  time.Duration `yaml:"-"`
	StreamTimeout time.Duration `yaml:"-"`
	ReconnectMin  time.Duration `yaml:"-"`
	ReconnectMax  time.Duration `yaml:"-"`

	ActivityHoldYAML  durationValue `yaml:"activity_hold"`
	StreamTimeoutYAML durationValue `yaml:"stream_timeout"`
	ReconnectMinYAML  durationValue `yaml:"reconnect_min"`
	ReconnectMaxYAML  durationValue `yaml:"reconnect_max"`
}

func loadConfig(path string) (clientConfig, string, error) {
	var config clientConfig
	content, err := readRegularFile(path, false)
	if err != nil {
		return config, "", fmt.Errorf("read config: %w", err)
	}
	decoder := yaml.NewDecoder(bytes.NewReader(content))
	decoder.KnownFields(true)
	if err := decoder.Decode(&config); err != nil {
		return config, "", fmt.Errorf("parse config: %w", err)
	}
	if err := applyAndValidateConfig(&config); err != nil {
		return config, "", err
	}
	tokenBytes, err := readRegularFile(config.TokenFile, true)
	if err != nil {
		return config, "", fmt.Errorf("read token file: %w", err)
	}
	token := strings.TrimSpace(string(tokenBytes))
	if token == "" || len(token) > 4096 || strings.IndexFunc(token, unicode.IsControl) >= 0 {
		return config, "", fmt.Errorf("token file must contain one non-empty token without control characters")
	}
	return config, token, nil
}

func parseGatewayURL(raw string) (string, error) {
	endpoint, err := url.Parse(raw)
	if err != nil {
		return "", fmt.Errorf("parse gateway_url: %w", err)
	}
	if endpoint.Scheme != "https" {
		return "", fmt.Errorf("gateway_url must use https")
	}
	if endpoint.Host == "" {
		return "", fmt.Errorf("gateway_url must include a host")
	}
	if endpoint.User != nil {
		return "", fmt.Errorf("gateway_url must not contain credentials")
	}
	if endpoint.Path != "/api/v1/status/events" {
		return "", fmt.Errorf("gateway_url path must be /api/v1/status/events")
	}
	if endpoint.RawQuery != "" || endpoint.Fragment != "" {
		return "", fmt.Errorf("gateway_url must not contain a query or fragment")
	}
	return endpoint.String(), nil
}

func applyAndValidateConfig(config *clientConfig) error {
	endpoint, err := parseGatewayURL(config.GatewayURL)
	if err != nil {
		return err
	}
	config.GatewayURL = endpoint
	if !filepath.IsAbs(config.TokenFile) {
		return fmt.Errorf("token_file must be an absolute path")
	}
	if config.CAFile != "" && !filepath.IsAbs(config.CAFile) {
		return fmt.Errorf("ca_file must be an absolute path")
	}
	config.LED = strings.ToUpper(config.LED)
	if config.LED == "" {
		config.LED = "A1"
	}
	if config.LED != "A1" && config.LED != "A2" {
		return fmt.Errorf("led must be A1 or A2")
	}

	config.ActivityHold = durationOrDefault(config.ActivityHoldYAML, 750*time.Millisecond)
	config.StreamTimeout = durationOrDefault(config.StreamTimeoutYAML, 45*time.Second)
	config.ReconnectMin = durationOrDefault(config.ReconnectMinYAML, time.Second)
	config.ReconnectMax = durationOrDefault(config.ReconnectMaxYAML, 30*time.Second)
	if config.ActivityHold < 50*time.Millisecond || config.ActivityHold > 10*time.Second {
		return fmt.Errorf("activity_hold must be between 50ms and 10s")
	}
	if config.StreamTimeout <= 15*time.Second {
		return fmt.Errorf("stream_timeout must be greater than the 15s gateway heartbeat interval")
	}
	if config.ReconnectMin <= 0 || config.ReconnectMax < config.ReconnectMin {
		return fmt.Errorf("reconnect interval range is invalid")
	}
	return nil
}

func durationOrDefault(value durationValue, fallback time.Duration) time.Duration {
	if value == 0 {
		return fallback
	}
	return time.Duration(value)
}

func readRegularFile(path string, protected bool) ([]byte, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("not a regular non-symlink file: %s", path)
	}
	if protected && info.Mode().Perm()&0o027 != 0 {
		return nil, fmt.Errorf("unsafe token permissions %04o: group write/execute and all other access must be disabled", info.Mode().Perm())
	}
	return os.ReadFile(path)
}
